CREATE OR REPLACE VIEW `vwprovvcoordinamento` AS select `v`.`id_pratica` AS `id_pratica`,`v`.`massimo` AS `massimo`,`v`.`minimo` AS `minimo` from ((`vwcoordinamentobase` `v` join `provvigioni` `p0` on((`p0`.`importo` = `v`.`minimo`))) join `provvigioni` `p1` on((`p1`.`importo` = `v`.`massimo`))) where ((`p0`.`denominazione_riferimento` <> `p1`.`denominazione_riferimento`) and (`v`.`minimo` > 0))
